	    public void EncodeBase64NVARCHARFields(AirlinePM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.RegistrationNotes)) //T4 find type == nText 
            {
                entityPM.RegistrationNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.RegistrationNotes));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.DeclineNotes)) //T4 find type == nText 
            {
                entityPM.DeclineNotes = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.DeclineNotes));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
		}
